messages.content:
/**
 *
 */
namespace AgnesAigc {
  /**
   * Generate one image from original_prompt and enhanced_prompt. Saves it in managed image artifacts; after registration succeeds, link the final Primary file path using standard Markdown.
   */
  export async function textToImage(input: TextToImageInput): Promise<TextToImageOutput>

  /**
   * Generate one video from original_prompt and an enhanced English motion prompt. Polls the task and saves it in managed video artifacts; after registration succeeds, link the final Primary file path using standard Markdown.
   */
  export async function textToVideo(input: TextToVideoInput): Promise<TextToVideoOutput>

  /**
   * Edit a reference image using original_prompt and enhanced_prompt. Accepts an HTTPS URL, local path, metadata JSON, or data URI; derives ratio when omitted. After registration succeeds, link the final Primary file path using standard Markdown.
   */
  export async function imageToImage(input: ImageToImageInput): Promise<ImageToImageOutput>

  /**
   * Generate a video from a reference image and enhanced motion prompt. Accepts an HTTPS URL, local path, metadata JSON, or data URI. After registration succeeds, link the final Primary file path using standard Markdown.
   */
  export async function imageToVideo(input: ImageToVideoInput): Promise<ImageToVideoOutput>
}

/**
 *
 */
namespace AgnesBrowser {
  /**
   * List MCP startup tool profiles and how to enable them.
   */
  export async function agentBrowserToolsProfiles(input: AgentBrowserToolsProfilesInput = {}): Promise<any>

  /**
   * Launch the browser and optionally navigate to a URL. On Windows, owned headless Chrome uses a private desktop and its process tree closes with the daemon, including forced termination. Headed browsers use the interactive desktop. Successful navigation responses include WebMCP availability metadata when the page exposes allowed tools.
   */
  export async function agentBrowserOpen(input: AgentBrowserOpenInput = {}): Promise<any>

  /**
   * Fetch a URL as agent-readable text, preferring text/markdown. Omit url to read the active tab.
   */
  export async function agentBrowserRead(input: AgentBrowserReadInput = {}): Promise<any>

  /**
   * Return an accessibility-tree snapshot with reusable element refs.
   */
  export async function agentBrowserSnapshot(input: AgentBrowserSnapshotInput = {}): Promise<any>

  /**
   * Click an element by @ref or CSS selector.
   */
  export async function agentBrowserClick(input: AgentBrowserClickInput): Promise<any>

  /**
   * Clear and fill an input by @ref or CSS selector.
   */
  export async function agentBrowserFill(input: AgentBrowserFillInput): Promise<any>

  /**
   * Type text into an element by @ref or CSS selector.
   */
  export async function agentBrowserType(input: AgentBrowserTypeInput): Promise<any>

  /**
   * Press a key at the current focus.
   */
  export async function agentBrowserPress(input: AgentBrowserPressInput): Promise<any>

  /**
   * Check a checkbox or switch.
   */
  export async function agentBrowserCheck(input: AgentBrowserCheckInput): Promise<any>

  /**
   * Uncheck a checkbox or switch.
   */
  export async function agentBrowserUncheck(input: AgentBrowserUncheckInput): Promise<any>

  /**
   * Select one or more options in a select element.
   */
  export async function agentBrowserSelect(input: AgentBrowserSelectInput): Promise<any>

  /**
   * Scroll the page or an element.
   */
  export async function agentBrowserScroll(input: AgentBrowserScrollInput = {}): Promise<any>

  /**
   * Wait for a fixed time.
   */
  export async function agentBrowserWaitMs(input: AgentBrowserWaitMsInput): Promise<any>

  /**
   * Wait for an element to appear.
   */
  export async function agentBrowserWaitForSelector(input: AgentBrowserWaitForSelectorInput): Promise<any>

  /**
   * Wait for text to appear.
   */
  export async function agentBrowserWaitForText(input: AgentBrowserWaitForTextInput): Promise<any>

  /**
   * Wait for a page load state.
   */
  export async function agentBrowserWaitForLoad(input: AgentBrowserWaitForLoadInput): Promise<any>

  /**
   * Capture a screenshot and return the saved path. Small PNG/JPEG screenshots are also returned as image content.
   */
  export async function agentBrowserScreenshot(input: AgentBrowserScreenshotInput = {}): Promise<any>

  /**
   * Get visible text from an element.
   */
  export async function agentBrowserGetText(input: AgentBrowserGetTextInput): Promise<any>

  /**
   * Get the current page URL.
   */
  export async function agentBrowserGetUrl(input: AgentBrowserGetUrlInput = {}): Promise<any>

  /**
   * Get the current page title.
   */
  export async function agentBrowserGetTitle(input: AgentBrowserGetTitleInput = {}): Promise<any>

  /**
   * Run JavaScript in the page using stdin to avoid shell escaping.
   */
  export async function agentBrowserEval(input: AgentBrowserEvalInput): Promise<any>

  /**
   * Close the current browser session.
   */
  export async function agentBrowserClose(input: AgentBrowserCloseInput = {}): Promise<any>

  /**
   * Navigate back.
   */
  export async function agentBrowserBack(input: AgentBrowserBackInput = {}): Promise<any>

  /**
   * Navigate forward.
   */
  export async function agentBrowserForward(input: AgentBrowserForwardInput = {}): Promise<any>

  /**
   * Reload the page.
   */
  export async function agentBrowserReload(input: AgentBrowserReloadInput = {}): Promise<any>

  /**
   * Open a new tab after applying session setup before its first navigation.
   */
  export async function agentBrowserTabNew(input: AgentBrowserTabNewInput = {}): Promise<any>

  /**
   * List tabs.
   */
  export async function agentBrowserTabList(input: AgentBrowserTabListInput = {}): Promise<any>

  /**
   * Switch to a tab by id (t1), label, or CDP target id. Switching also binds the session to that tab.
   */
  export async function agentBrowserTabSwitch(input: AgentBrowserTabSwitchInput): Promise<any>

  /**
   * Close a tab by id (t1), label, or CDP target id. Omit to close the current tab.
   */
  export async function agentBrowserTabClose(input: AgentBrowserTabCloseInput = {}): Promise<any>
}

/**
 *
 */
namespace Summon {
  /**
   * List or load recipes, agents, and subrecipes, and inspect background tasks. With a task ID, wait by default; use peek to poll or cancel to stop it.
   */
  export async function load(input: LoadInput = {}): Promise<any>

  /**
   * Run an ad-hoc task or named source in an isolated subagent. It sees only supplied instructions and context. Use async for parallel work, partition writes by file, and collect async results with load.
   */
  export async function delegate(input: DelegateInput = {}): Promise<any>
}

/**
 *
 */
namespace Summarize {
  /**
   * Load files/directories deterministically and get an LLM summary in a single call. More efficient than subagent when you know what to analyze. Specify paths (files or dirs that will be recursively expanded, respecting top-level .gitignore), a question to focus the summary, and optionally filter by file extensions.
   */
  export async function summarize(input: SummarizeInput): Promise<any>
}

/**
 *
 */
namespace AgnesResearch {
  /**
   * Write one complete Markdown research report and JSON manifest to managed artifacts. Include auditable evidence, conflicts, blocked sources, and honest confidence when available; returns local paths and quality warnings.
   */
  export async function writeResearchReport(input: WriteResearchReportInput): Promise<WriteResearchReportOutput>

  /**
   * Append one or more structured evidence entries to the managed research ledger. Batch multiple entries in evidence; returns quality warnings for hard-to-audit records.
   */
  export async function recordEvidence(input: RecordEvidenceInput): Promise<RecordEvidenceOutput>
}

/**
 *
 */
namespace Analyze {
  /**
   * Analyze code structure in 3 modes: 1) Directory overview - file tree with LOC/function/class counts to max_depth. 2) File details - functions, classes, imports. 3) Symbol focus - call graphs across directory to max_depth (requires file or directory path, case-sensitive). Typical flow: directory → files → symbols. Functions called >3x show •N.
   */
  export async function analyze(input: AnalyzeInput): Promise<any>
}

/**
 *
 */
namespace Extensionmanager {
  /**
   * List extensions that may provide a missing capability. Enable a relevant result with manage_extensions, then continue with its new tools.
   */
  export async function searchAvailableExtensions(input: { [key: string]: any | undefined } = {}): Promise<any>

  /**
   * List resources from one extension, or all extensions when extension_name is omitted.
   */
  export async function listResources(input: ListResourcesInput = {}): Promise<any>

  /**
   * Read a resource from its owning extension. If the owner is unknown, call list_resources first.
   */
  export async function readResource(input: ReadResourceInput): Promise<any>
}

/**
 *
 */
namespace Chatrecall {
  /**
   * Search past chat or load session summaries. Use when it is clear user expects some memory or context.
   *
   * search mode (query): Use multiple keywords/synonyms. Returns messages grouped by session, ordered by recency. Supports date filters.
   * load mode (session_id): Returns first/last 3 messages of a session.
   *
   */
  export async function chatrecall(input: ChatrecallInput = {}): Promise<any>
}

/**
 *
 */
namespace Developer {
  /**
   * Fallback UTF-8 text-file reader when shell fails or is unavailable. You MUST try shell first. Do not use it for binary formats such as PDF, DOCX, or XLSX; use a matching extension tool instead. Accepts absolute paths, including files outside the current workspace when the user provides them. Optionally start at a 1-based line and limit how many lines are returned.
   */
  export async function read(input: ReadInput): Promise<any>

  /**
   * Create or overwrite a UTF-8 text file. Do not use it for binary formats such as PDF, DOCX, XLSX, PPTX, or XMIND; use a matching extension tool instead. Creates parent directories if needed. In Full access (auto) mode, destinations outside the current workspace are denied without a confirmation prompt, regardless of user_specified_output. In approval modes, for an external destination explicitly requested by the user, set user_specified_output=true and wait for this call's confirmation; otherwise the write is denied.
   */
  export async function write(input: WriteInput): Promise<any>

  /**
   * Edit a file by finding and replacing text. The before text must match exactly and uniquely. Use empty after text to delete. In Full access (auto) mode, destinations outside the current workspace are denied without a confirmation prompt, regardless of user_specified_output. In approval modes, for an external destination explicitly requested by the user, set user_specified_output=true and wait for this call's confirmation; otherwise the edit is denied.
   */
  export async function edit(input: EditInput): Promise<any>

  /**
   * Execute a shell command in the current dir. Commands run under `bash` (set AGNES_SHELL to override) - write command strings in that shell's syntax, which may differ from the user's interactive terminal. This platform does not expose the Windows `shell` selection parameter. Honor any user-requested interpreter/version constraints; report an unavailable or incompatible environment instead of silently switching interpreters. Inspect stderr and verify expected results even when exit_code is zero. Returns stdout and stderr as separate fields. Each stream is limited to 2000 lines; longer outputs are saved to a temporary file. Ordinary shell commands have network access disabled by the OS sandbox by default. Full access (Auto) mode or approval of this shell call enables network access for the invocation and its descendants. In other modes, set network=true to request network access for a call that would otherwise run without approval. Existing file restrictions remain in place. Managed CLI invocations retain their own execution policy. Hidden credential files or environment variables do not prove the host has no credentials.
   */
  export async function shell(input: ShellInput): Promise<ShellOutput>

  /**
   * Search file contents with cross-platform scope controls. By default, traversal stays inside the workspace, respects ignore files, skips hidden paths, and does not follow symlinks. Set include_hidden, include_ignored, or follow_symlinks only when those paths are relevant.
   */
  export async function search(input: SearchInput): Promise<any>

  /**
   * List a directory tree with line counts. Traversal respects .gitignore rules.
   */
  export async function tree(input: TreeInput): Promise<any>

  /**
   * Read an image from a local file path or http(s) URL and return it as image content for the model to inspect. Supports png, jpeg, gif, and webp.
   */
  export async function readImage(input: ReadImageInput): Promise<any>
}

/**
 *
 */
namespace AgnesWebSearch {
  /**
   * Search the public web and return titles, URLs, and snippets. Prefer explicitly requested or configured search tools. Batch known query angles; use research modes for broad evidence and read important URLs before relying on precise claims.
   */
  export async function webSearch(input: WebSearchInput = {}): Promise<WebSearchOutput>

  /**
   * Read one or more public webpages and return extracted text, quote candidates, and blocked status. Batch primary URLs; blocked or empty pages are not evidence and should not be retried.
   */
  export async function readWebpage(input: ReadWebpageInput = {}): Promise<ReadWebpageOutput>

  /**
   * Search for and locally verify web images. Prefer explicitly requested or configured image tools. Batch multiple subjects. Do not publish candidates as user-facing artifacts unless the user asked to see or save the images. For reports, slides, HTML, or other documents set source_material=true.
   */
  export async function imageSearch(input: ImageSearchInput = {}): Promise<ImageSearchOutput>

  /**
   * Search Wikipedia for canonical background on people, places, organizations, concepts, and historical topics; use web search for current information.
   */
  export async function encyclopediaSearch(input: EncyclopediaSearchInput): Promise<EncyclopediaSearchOutput>

  /**
   * Search Wikidata for an entity and stable Q-id. Use before entity_facts when the Q-id is unknown; never invent Q-ids.
   */
  export async function entitySearch(input: EntitySearchInput): Promise<EntitySearchOutput>

  /**
   * Fetch a bounded structured fact list for a known Wikidata Q-id. Use entity_search first when the Q-id is unknown.
   */
  export async function entityFacts(input: EntityFactsInput): Promise<EntityFactsOutput>
}

/**
 *
 */
namespace AgnesSlide {
  /**
   * Create or reset the Agnes slide deck workspace under the current project.
   */
  export async function createDeck(input: CreateDeckInput): Promise<CreateDeckOutput>

  /**
   * Write the authoritative deck_outline.json for the slide deck. Slides must use the exact one-based sequence slide-001/index 1, slide-002/index 2, and so on; never use zero-based indexes or slide-01-style IDs.
   */
  export async function writeOutline(input: WriteOutlineInput): Promise<WriteOutlineOutput>

  /**
   * Write global visual rules to design_system.txt.
   */
  export async function writeDesignSystem(input: WriteDesignSystemInput): Promise<WriteDesignSystemOutput>

  /**
   * Record slide research notes, source URLs, or image references under deck/source. Prefer one call with sources:[...] for multiple assets. `source` still works for a single entry. For images, pass the exact local_path returned by image_search; this tool will copy/materialize it instead of requiring shell file operations.
   */
  export async function recordSource(input: RecordSourceInput = {}): Promise<RecordSourceOutput>

  /**
   * Write one fixed-size 1280x720 slide HTML page with class="slide". slide_id must exist in the outline. After materials are ready, emit remaining outline write_slide_page calls in the SAME assistant turn, at most 5 per turn, until every outline slide_id has HTML. Do not write one page per turn, and do not emit more than 5 write_slide_page calls in one turn (larger HTML batches hit the output token limit and become unparseable). First pass must include visual support (local image or structured visual) and no placeholder text. Prefer compact HTML. Optional sources[] records assets with the page. Use exact image local_path values returned by image_search/agnes_slide__record_source; do not invent source/images filenames. The page must not use scrollable overflow or clipped off-canvas content.
   */
  export async function writeSlidePage(input: WriteSlidePageInput): Promise<WriteSlidePageOutput>

  /**
   * Validate outline, slide HTML files, dimensions, placeholders, local image references, scrollable overflow, and source manifests. Structural failures block finalize/export. Visual-support notes are warnings: enrich those slide_ids in the same next turn with a local image or structured visual, at most 5 write_slide_page calls; they do not block export. When multiple slide_ids have structural failures, rewrite them with same-turn multi agnes_slide__write_slide_page in the next turn (at most 5) — never repair one failing page per turn.
   */
  export async function validateDeck(input: any): Promise<ValidateDeckOutput>

  /**
   * Check shared Node, npm, converter files, dependencies, and Playwright Chromium before PPTX export.
   */
  export async function checkExportEnvironment(input: any): Promise<CheckExportEnvironmentOutput>

  /**
   * Build the intermediate HTML deck files used for preview and export. Set final_output to the exact user-facing format that must follow: pptx by default, or html or pdf only when explicitly requested. This tool does not publish a user-facing artifact.
   */
  export async function finalizeDeck(input: FinalizeDeckInput = {}): Promise<FinalizeDeckOutput>

  /**
   * Publish the finalized HTML slide deck as the user-facing artifact when the user explicitly asks for HTML instead of PPTX.
   */
  export async function exportHtml(input: ExportHtmlInput = {}): Promise<ExportHtmlOutput>

  /**
   * Export a finalized Agnes slide deck to PDF (fixed 1280x720 slide pages). Requires an existing deck with deck_outline.json and confirmed_by_user=true. Do not use this for ordinary Markdown reports. Only when the user explicitly asks to export, convert, turn, save, or download a Markdown report as PDF, call agnes_artifacts__export_document_pdf instead.
   */
  export async function exportPdf(input: ExportPdfInput = {}): Promise<ExportPdfOutput>

  /**
   * Export the finalized HTML deck to PPTX and automatically register it as the user-facing artifact. After a successful call, do not export again or call present_artifacts for the same PPTX.
   */
  export async function exportPptx(input: ExportPptxInput = {}): Promise<ExportPptxOutput>
}

/**
 *
 */
namespace Todo {
  /**
   * Overwrite the entire TODO content.
   *
   * The content persists across conversation turns and compaction. Use this for:
   * - Task tracking and progress updates
   * - Important notes and reminders
   *
   * Complete every TODO update before starting the final user-facing response. Never
   * call this tool after the final response has started, and do not track writing,
   * sending, or presenting the final response itself as a TODO item.
   *
   * WARNING: This operation completely replaces the existing content. Always include
   * all content you want to keep, not just the changes.
   *
   */
  export async function todoWrite(input: TodoWriteInput): Promise<any>
}

/**
 *
 */
namespace Skills {
  /**
   * Load a skill's full content into your context so you can follow its instructions.
   *
   * Skills are listed in your system instructions. When you need to use one, load it first to get the detailed instructions.
   *
   * Examples:
   * - load_skill(name: "gdrive") → Loads the gdrive skill instructions
   * - load_skill(name: "my-skill", args: "the arguments for the skill") → Loads a skill with arguments
   * - load_skill(name: "my-skill/template.md") → Loads a supporting file
   */
  export async function loadSkill(input: LoadSkillInput): Promise<any>

  /**
   * Create a new reusable skill and save it to the user's skills directory. The skill becomes usable immediately via load_skill, or by typing $name in the chat input.
   *
   * Before creating one, load the "skill-creator" skill for authoring guidelines.
   */
  export async function createSkill(input: CreateSkillInput): Promise<any>
}

/**
 *
 */
namespace Computercontroller {
  /**
   *
   *             macOS UI automation via Peekaboo CLI. Pass a subcommand string as `command`.
   *
   *             Core workflow: see → click → type
   *             1. see --app Safari --annotate  (get annotated screenshot with element IDs)
   *             2. click --on B3               (click element by ID)
   *             3. type "hello" --return       (type text, press enter)
   *
   *             Key commands: see, image, click, type, press, hotkey, paste, scroll, drag,
   *             swipe, move, app, window, list, menu, menubar, dock, dialog, clipboard,
   *             space, open, permissions.
   *
   *             Targeting: --app Name, --window-title, --window-id, --on ID, --coords x,y
   *             Set capture_screenshot=true to verify UI state after actions.
   *             See extension instructions for full command reference and examples.
   *
   */
  export async function computerControl(input: ComputerControlInput): Promise<any>

  /**
   *
   *             Process DOCX files to extract text and create/update documents.
   *             Supports operations:
   *             - extract_text: Extract all text content and structure (headings, TOC) from the DOCX
   *             - update_doc: Create a new DOCX or update existing one with provided content
   *               Modes:
   *               - append: Add content to end of document (default)
   *               - replace: Replace specific text with new content
   *               - structured: Add content with specific heading level and styling
   *               - add_image: Add an image to the document (with optional caption)
   *
   *             Use this when there is a .docx file that needs to be processed or created.
   *
   */
  export async function docxTool(input: DocxToolInput): Promise<any>

  /**
   *
   *             Process PDF files to extract text and images.
   *             Supports operations:
   *             - extract_text: Extract all text content from the PDF
   *             - extract_images: Extract and save embedded images to PNG files
   *
   *             Use this when there is a .pdf file or files that need to be processed.
   *
   */
  export async function pdfTool(input: PdfToolInput): Promise<any>

  /**
   *
   *             Process Excel (XLSX) files to read and manipulate spreadsheet data.
   *             Supports operations:
   *             - list_worksheets: List all worksheets in the workbook (returns name, index, column_count, row_count)
   *             - get_columns: Get column names from a worksheet (returns values from the first row)
   *             - get_range: Get values and formulas from a cell range (e.g., 'A1:C10') (returns a 2D array organized as [row][column])
   *             - find_text: Search for text in a worksheet (returns a list of (row, column) coordinates)
   *             - update_cell: Update a single cell's value (returns confirmation message)
   *             - get_cell: Get value and formula from a specific cell (returns both value and formula if present)
   *             - save: Save changes back to the file (returns confirmation message)
   *
   *             Use this when working with Excel spreadsheets to analyze or modify data.
   *
   */
  export async function xlsxTool(input: XlsxToolInput): Promise<any>
}

