   */
  export async function write(input: WriteInput): Promise<any>

  /**
   * Edit a file by finding and replacing text. The before text must match exactly and uniquely. Use empty after text to delete. In Full access (auto) mode, destinations outside the current workspace are denied without a confirmation prompt, regardless of user_specified_output. In approval modes, for an external destination explicitly requested by the user, set user_specified_output=true and wait for this call's confirmation; otherwise the edit is denied.
