    const ext = dot >= 0 ? fname.slice(dot + 1).toLowerCase() : "(无扩展名)";
    extDist[ext] = (extDist[ext] || 0) + 1;
  }

  return {
    exit_code: out.exit_code,
    sampleLines: lines.slice(0, 15),
    storeDirFileCounts: dirs,
    extDistribution: Object.entries(extDist).sort((a, b) => b[1] - a[1])
