async function run() {
  const root = "/Users/billtse/Desktop/青瓷店铺";
  const cmd = `find "${root}" -type f -print 2>/dev/null`;
  const out = await Developer.shell({ command: cmd, timeout_secs: 120 });

  const lines = out.stdout.split("\n").map(s => s.trim()).filter(Boolean);

  const imgExts = new Set([
    "jpg","jpeg","png","gif","webp","bmp","tiff","tif","svg",
    "heic","heif","ico","psd","raw","dng","cr2","nef"
  ]);

  // store -> { count, exts }
  const storeMap: Record<string, { count: number; exts: Record<string, number> }> = {};

  for (const abs of lines) {
    const rel = abs.startsWith(root + "/") ? abs.slice(root.length + 1) : "(根目录文件)";
    const parts = rel.split("/");
    const fname = parts[parts.length - 1];
    const dot = fname.lastIndexOf(".");
    const ext = dot >= 0 ? fname.slice(dot + 1).toLowerCase() : "";
    if (!imgExts.has(ext)) continue;

    const store = parts.length > 1 ? parts[0] : "(根目录散文件)";
    if (!storeMap[store]) storeMap[store] = { count: 0, exts: {} };
    storeMap[store].count++;
    const e = ext.toUpperCase() || "(无扩展名)";
    storeMap[store].exts[e] = (storeMap[store].exts[e] || 0) + 1;
  }

  const rows = Object.entries(storeMap)
    .map(([store, v]) => {
      const top = Object.entries(v.exts).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0];
      return { store, count: v.count, topExt: top ? top[0] : "-", topCount: top ? top[1] : 0 };
    })
    .sort((a, b) => b.count - a.count || a.store.localeCompare(b.store, "zh"));

  return {
    exit_code: out.exit_code,
    stderr: out.stderr ? out.stderr.slice(0, 500) : "",
    totalFilesScanned: lines.length,
    storeCount: rows.length,
    rows
  };
}
