async function run() {
  const root = "/Users/billtse/Desktop/青瓷店铺";
  const out = await Developer.shell({
    command: `find "${root}" -type f \\( -iname '*.jpg' -o -iname '*.jpeg' -o -iname '*.png' -o -iname '*.gif' -o -iname '*.webp' -o -iname '*.bmp' -o -iname '*.tiff' -o -iname '*.tif' -o -iname '*.svg' -o -iname '*.heic' \\) -print 2>/dev/null | awk -F'/' '{n=split($0,a,"/"); }' ; find "${root}" -type f \\( -iname '*.jpg' -o -iname '*.jpeg' -o -iname '*.png' -o -iname '*.gif' -o -iname '*.webp' -o -iname '*.bmp' -o -iname '*.tiff' -o -iname '*.tif' -o -iname '*.svg' -o -iname '*.heic' \\) -print 2>/dev/null | awk -v root="${root}/" '{ p=$0; sub(root,"",p); n=split(p,a,"/"); store = (n>1)?a[1]:"(根目录散文件)"; f=a[n]; e=f; i=0; for(i=length(f);i>=0;i--) if (substr(f,i,1)=="."){e=substr(f,i+1);break}; ext=toupper(ext e==f?"(无)":ext); ext=toupper(e); print store "\\t" ext }' | sort | uniq -c | sort -k2,2 -k3,3`,
    timeout_secs: 600
  });
  const lines = out.stdout.trim().split("\n").map(s => s.trim()).filter(Boolean);
  // lines: "   123 store \t EXT"
  const byStore: Record<string, { total: number; topExt: string; topCount: number; dist: Record<string, number> }> = {};
  for (const l of lines) {
    const m = l.match(/^(\d+)\s+(.+)\t(\S+)$/);
    if (!m) continue;
    const cnt = parseInt(m[1], 10);
    const store = m[2].trim();
    const ext = m[3].toUpperCase();
    if (!byStore[store]) byStore[store] = { total: 0, topExt: "-", topCount: 0, dist: {} };
    byStore[store].total += cnt;
    byStore[store].dist[ext] = (byStore[store].dist[ext] || 0) + cnt;
  }
  for (const s of Object.values(byStore)) {
    const top = Object.entries(s.dist).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0];
    s.topExt = top ? top[0] : "-";
    s.topCount = top ? top[1] : 0;
  }
  return {
    exit_code: out.exit_code,
    err: out.stderr ? out.stderr.slice(0, 300) : "",
    rowCount: lines.length,
    stores: Object.entries(byStore).map(([k, v]) => ({
      store: k,
      imgCount: v.total,
      topExt: v.topExt,
      topExtPct: v.total ? Math.round((v.topCount / v.total) * 100) : 0,
      top3: Object.entries(v.dist).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, 3)
    }))
  };
}

